  1→// UEBridgeStyle.cpp
  2→// Centralized Slate style set for UE Bridge UI.
  3→// Defines all named color and font tokens consumed by the 6 UI widgets.
  4→
  5→#include "UEBridgeStyle.h"
  6→#include "Styling/CoreStyle.h"
  7→#include "Styling/SlateTypes.h"
  8→
  9→TSharedPtr<FSlateStyleSet> FUEBridgeStyle::StyleInstance = nullptr;
 10→
 11→FName FUEBridgeStyle::GetStyleSetName()
 12→{
 13→	static FName StyleSetName(TEXT("UEBridgeStyle"));
 14→	return StyleSetName;
 15→}
 16→
 17→void FUEBridgeStyle::Initialize()
 18→{
 19→	if (!StyleInstance.IsValid())
 20→	{
 21→		StyleInstance = Create();
 22→		FSlateStyleRegistry::RegisterSlateStyle(*StyleInstance);
 23→	}
 24→}
 25→
 26→void FUEBridgeStyle::Shutdown()
 27→{
 28→	if (StyleInstance.IsValid())
 29→	{
 30→		FSlateStyleRegistry::UnRegisterSlateStyle(*StyleInstance);
 31→		StyleInstance.Reset();
 32→	}
 33→}
 34→
 35→const ISlateStyle& FUEBridgeStyle::Get()
 36→{
 37→	if (!StyleInstance.IsValid())
 38→	{
 39→		// Lazy init: CDO construction can reach here before StartupModule()
 40→		Initialize();
 41→	}
 42→	return *StyleInstance;
 43→}
 44→
 45→FLinearColor FUEBridgeStyle::GetColor(const FName& PropertyName)
 46→{
 47→	return Get().GetSlateColor(PropertyName).GetSpecifiedColor();
 48→}
 49→
 50→FSlateFontInfo FUEBridgeStyle::GetFont(const FName& PropertyName)
 51→{
 52→	return Get().GetFontStyle(PropertyName);
 53→}
 54→
 55→TSharedRef<FSlateStyleSet> FUEBridgeStyle::Create()
 56→{
 57→	TSharedRef<FSlateStyleSet> Style = MakeShareable(new FSlateStyleSet(GetStyleSetName()));
 58→
 59→	// -------------------------------------------------------------------------
 60→	// Colors
 61→	// -------------------------------------------------------------------------
 62→
 63→	// Backgrounds
 64→	Style->Set("Color.Background",      FSlateColor(FLinearColor(0.02f, 0.02f, 0.05f, 0.98f)));
 65→	Style->Set("Color.BackgroundSolid",  FSlateColor(FLinearColor(0.02f, 0.02f, 0.05f, 1.0f)));
 66→
 67→	// Primary accent — cyan family
 68→	Style->Set("Color.Cyan",            FSlateColor(FLinearColor(0.36f, 1.0f, 0.86f, 1.0f)));
 69→	Style->Set("Color.CyanDim",         FSlateColor(FLinearColor(0.36f, 1.0f, 0.86f, 0.8f)));
 70→	Style->Set("Color.CyanFaint",       FSlateColor(FLinearColor(0.36f, 1.0f, 0.86f, 0.9f)));
 71→
 72→	// Secondary accent — gold
 73→	Style->Set("Color.Gold",            FSlateColor(FLinearColor(1.0f, 0.8f, 0.2f, 1.0f)));
 74→
 75→	// Text hierarchy
 76→	Style->Set("Color.TextPrimary",     FSlateColor(FLinearColor(0.9f, 0.9f, 0.9f, 1.0f)));
 77→	Style->Set("Color.TextSecondary",   FSlateColor(FLinearColor(0.7f, 0.7f, 0.8f, 1.0f)));
 78→	Style->Set("Color.TextDim",         FSlateColor(FLinearColor(0.5f, 0.5f, 0.6f, 1.0f)));
 79→	Style->Set("Color.TextMuted",       FSlateColor(FLinearColor(0.4f, 0.4f, 0.5f, 1.0f)));
 80→
 81→	// Semantic colors
 82→	Style->Set("Color.Insight",         FSlateColor(FLinearColor(0.7f, 0.8f, 0.7f, 1.0f)));
 83→	Style->Set("Color.IncompleteGray",  FSlateColor(FLinearColor(0.3f, 0.3f, 0.3f, 0.5f)));
 84→
 85→	// Button states
 86→	Style->Set("Color.ButtonNormal",    FSlateColor(FLinearColor(0.1f, 0.1f, 0.15f, 1.0f)));
 87→	Style->Set("Color.ButtonHovered",   FSlateColor(FLinearColor(0.2f, 0.4f, 0.5f, 1.0f)));
 88→
 89→	// Question depth tiers
 90→	Style->Set("Color.DepthSurface",    FSlateColor(FLinearColor(0.5f, 0.8f, 0.5f, 1.0f)));
 91→	Style->Set("Color.DepthPatterns",   FSlateColor(FLinearColor(0.3f, 0.8f, 0.8f, 1.0f)));
 92→	Style->Set("Color.DepthFeelings",   FSlateColor(FLinearColor(1.0f, 0.5f, 0.45f, 1.0f)));
 93→	Style->Set("Color.DepthCore",       FSlateColor(FLinearColor(1.0f, 0.85f, 0.3f, 1.0f)));
