 99→	Style->Set("Font.Title",            FCoreStyle::GetDefaultFontStyle("Bold",    56));
100→	Style->Set("Font.Heading",          FCoreStyle::GetDefaultFontStyle("Bold",    36));
101→	Style->Set("Font.Subtitle",         FCoreStyle::GetDefaultFontStyle("Regular", 18));
102→	Style->Set("Font.Body",             FCoreStyle::GetDefaultFontStyle("Regular", 16));
103→	Style->Set("Font.Question",         FCoreStyle::GetDefaultFontStyle("Regular", 24));
104→	Style->Set("Font.Option",           FCoreStyle::GetDefaultFontStyle("Regular", 18));
105→	Style->Set("Font.Progress",         FCoreStyle::GetDefaultFontStyle("Regular", 14));
106→	Style->Set("Font.Caption",          FCoreStyle::GetDefaultFontStyle("Regular", 12));
107→	Style->Set("Font.Small",            FCoreStyle::GetDefaultFontStyle("Regular", 11));
108→	Style->Set("Font.Insight",          FCoreStyle::GetDefaultFontStyle("Regular", 13));
109→
110→	return Style;
111→}
