 1→// UEBridgeRuntime.Build.cs
 2→// Runtime module — ships in packaged builds.
 3→// Owns BridgeComponent, data types, UMG widgets, and polling-based file bridge.
 4→
 5→using UnrealBuildTool;
 6→using System.IO;
 7→
 8→public class UEBridgeRuntime : ModuleRules
 9→{
10→    public UEBridgeRuntime(ReadOnlyTargetRules Target) : base(Target)
11→    {
12→        PCHUsage = PCHUsageMode.UseExplicitOrSharedPCHs;
13→
14→        PublicIncludePaths.AddRange(new string[]
15→        {
16→            Path.Combine(ModuleDirectory, "Public"),
17→            Path.Combine(ModuleDirectory, "Public", "UI")
18→        });
19→
20→        PrivateIncludePaths.AddRange(new string[]
21→        {
22→            Path.Combine(ModuleDirectory, "Private"),
23→            Path.Combine(ModuleDirectory, "Private", "UI")
24→        });
25→
26→        // Core runtime dependencies — ship in packaged builds
27→        PublicDependencyModuleNames.AddRange(new string[]
28→        {
29→            "Core",
30→            "CoreUObject",
31→            "Engine",
32→            "InputCore",
33→            "Json",
34→            "JsonUtilities"
35→        });
36→
37→        // UMG / Slate for gameplay widgets
38→        PublicDependencyModuleNames.AddRange(new string[]
39→        {
40→            "Slate",
41→            "SlateCore",
42→            "UMG"
43→        });
44→
45→        // HTTP for runtime Remote Control communication
46→        PrivateDependencyModuleNames.Add("HTTP");
47→
48→        // Version definition — single source of truth
49→        PublicDefinitions.Add("BRIDGE_VERSION=TEXT(\"2.1.0\")");
50→
51→        // USD support flag: editor-only via pxr, runtime uses text-based USDA parser
52→        if (Target.bBuildEditor)
53→        {
54→            PublicDefinitions.Add("WITH_USD_SUPPORT=1");
55→        }
56→        else
57→        {
58→            PublicDefinitions.Add("WITH_USD_SUPPORT=0");
59→        }
60→    }
61→}
