 29→// === FILE WATCHING ===
 30→
 31→void UBridgeEditorSubsystem::StartWatching(const FString& BridgePath)
 32→{
 33→    if (bIsWatching)
 34→    {
 35→        if (WatchedPath == BridgePath)
 36→        {
 37→            return; // Already watching this path
 38→        }
 39→        StopWatching(); // Switch to new path
 40→    }
 41→
 42→    FDirectoryWatcherModule& DirWatcherModule =
 43→        FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
 44→    IDirectoryWatcher* DirWatcher = DirWatcherModule.Get();
 45→
 46→    if (!DirWatcher)
 47→    {
 48→        UE_LOG(LogUEBridge, Error, TEXT("Could not get DirectoryWatcher module"));
 49→        return;
 50→    }
 51→
 52→    IDirectoryWatcher::FDirectoryChanged Callback =
 53→        IDirectoryWatcher::FDirectoryChanged::CreateUObject(
 54→            this, &UBridgeEditorSubsystem::OnDirectoryChanged);
 55→
 56→    bool bSuccess = DirWatcher->RegisterDirectoryChangedCallback_Handle(
 57→        BridgePath, Callback, WatchHandle, 0);
 58→
 59→    if (bSuccess)
 60→    {
 61→        WatchedPath = BridgePath;
 62→        bIsWatching = true;
 63→        UE_LOG(LogUEBridge, Log, TEXT("Editor file watcher registered for: %s"), *BridgePath);
 64→    }
 65→    else
 66→    {
 67→        UE_LOG(LogUEBridge, Error, TEXT("Failed to register editor file watcher for: %s"), *BridgePath);
 68→    }
 69→}
 70→
 71→
 72→void UBridgeEditorSubsystem::StopWatching()
 73→{
 74→    if (!bIsWatching || !WatchHandle.IsValid())
 75→    {
 76→        return;
 77→    }
 78→
 79→    FDirectoryWatcherModule& DirWatcherModule =
 80→        FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
 81→    IDirectoryWatcher* DirWatcher = DirWatcherModule.Get();
 82→
 83→    if (DirWatcher)
 84→    {
 85→        DirWatcher->UnregisterDirectoryChangedCallback_Handle(WatchedPath, WatchHandle);
 86→        UE_LOG(LogUEBridge, Log, TEXT("Editor file watcher unregistered"));
 87→    }
 88→
 89→    bIsWatching = false;
 90→    WatchedPath.Empty();
 91→}
 92→
 93→
 94→void UBridgeEditorSubsystem::OnDirectoryChanged(const TArray<FFileChangeData>& Changes)
 95→{
 96→    for (const FFileChangeData& Change : Changes)
 97→    {
 98→        bool bIsUsdProfile = Change.Filename.EndsWith(TEXT("cognitive_profile.usda")) ||
 99→                             Change.Filename.EndsWith(TEXT("cognitive_substrate.usda"));
100→
101→        bool bIsBridgeState = Change.Filename.EndsWith(TEXT("state.json")) ||
102→                              Change.Filename.EndsWith(TEXT("bridge_state.usda"));
103→
104→        if (bIsBridgeState || bIsUsdProfile)
105→        {
106→            // Broadcast to any listeners (BridgeComponents, editor tools, etc.)
107→            OnBridgeFileChanged.Broadcast(Change.Filename, bIsUsdProfile);
108→        }
109→    }
110→}
