 26→void FPerceptionEndpoint::Start()
 27→{
 28→	if (bRunning)
 29→	{
 30→		return;
 31→	}
 32→
 33→	FHttpServerModule& HttpModule = FHttpServerModule::Get();
 34→	TSharedPtr<IHttpRouter> Router = HttpModule.GetHttpRouter(PERCEPTION_PORT);
 35→
 36→	if (!Router.IsValid())
 37→	{
 38→		UE_LOG(LogViewportPerception, Warning, TEXT("Failed to get HTTP router on port %d"), PERCEPTION_PORT);
 39→		return;
 40→	}
 41→
 42→	// GET /perception/frame
 43→	RouteHandles.Add(Router->BindRoute(
 44→		FHttpPath(TEXT("/perception/frame")),
 45→		EHttpServerRequestVerbs::VERB_GET,
 46→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleFrame)
 47→	));
 48→
 49→	// GET /perception/status
 50→	RouteHandles.Add(Router->BindRoute(
 51→		FHttpPath(TEXT("/perception/status")),
 52→		EHttpServerRequestVerbs::VERB_GET,
 53→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleStatus)
 54→	));
 55→
 56→	// PUT /perception/config
 57→	RouteHandles.Add(Router->BindRoute(
 58→		FHttpPath(TEXT("/perception/config")),
 59→		EHttpServerRequestVerbs::VERB_PUT,
 60→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleConfig)
 61→	));
 62→
 63→	// PUT /perception/start
 64→	RouteHandles.Add(Router->BindRoute(
 65→		FHttpPath(TEXT("/perception/start")),
 66→		EHttpServerRequestVerbs::VERB_PUT,
 67→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleStart)
 68→	));
 69→
 70→	// PUT /perception/stop
 71→	RouteHandles.Add(Router->BindRoute(
 72→		FHttpPath(TEXT("/perception/stop")),
 73→		EHttpServerRequestVerbs::VERB_PUT,
 74→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleStop)
 75→	));
 76→
 77→	// GET /perception/single
 78→	RouteHandles.Add(Router->BindRoute(
 79→		FHttpPath(TEXT("/perception/single")),
 80→		EHttpServerRequestVerbs::VERB_GET,
 81→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleSingle)
 82→	));
 83→
 84→	// PUT /perception/single
 85→	RouteHandles.Add(Router->BindRoute(
 86→		FHttpPath(TEXT("/perception/single")),
 87→		EHttpServerRequestVerbs::VERB_PUT,
 88→		FHttpRequestHandler::CreateRaw(this, &FPerceptionEndpoint::HandleSingle)
 89→	));
 90→
 91→	HttpModule.StartAllListeners();
 92→	bRunning = true;
 93→
 94→	UE_LOG(LogViewportPerception, Log, TEXT("HTTP endpoint started on port %d"), PERCEPTION_PORT);
 95→}
 96→
 97→void FPerceptionEndpoint::Stop()
 98→{
 99→	if (!bRunning)
100→	{
101→		return;
102→	}
103→
104→	FHttpServerModule& HttpModule = FHttpServerModule::Get();
105→	TSharedPtr<IHttpRouter> Router = HttpModule.GetHttpRouter(PERCEPTION_PORT);
106→
107→	if (Router.IsValid())
108→	{
109→		for (const FHttpRouteHandle& Handle : RouteHandles)
110→		{
111→			Router->UnbindRoute(Handle);
112→		}
113→	}
114→
115→	RouteHandles.Empty();
116→	bRunning = false;
117→
118→	UE_LOG(LogViewportPerception, Log, TEXT("HTTP endpoint stopped"));
119→}
