121→bool FPerceptionEndpoint::HandleFrame(const FHttpServerRequest& Request,
122→                                       const FHttpResultCallback& OnComplete)
123→{
124→	if (!Subsystem)
125→	{
126→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem not available\"}"), 503);
127→		return true;
128→	}
129→
130→	FPerceptionPacket Packet = Subsystem->GetLatestPacket();
131→
132→	if (!Packet.bValid)
133→	{
134→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"No frame available\"}"), 404);
135→		return true;
136→	}
137→
138→	// Build JSON response
139→	TSharedRef<FJsonObject> Root = MakeShared<FJsonObject>();
140→
141→	// Base64 encode the image
142→	FString ImageBase64 = FBase64::Encode(Packet.ImageData.GetData(), Packet.ImageData.Num());
143→	Root->SetStringField(TEXT("image"), ImageBase64);
144→	Root->SetNumberField(TEXT("width"), Packet.Width);
145→	Root->SetNumberField(TEXT("height"), Packet.Height);
146→	Root->SetStringField(TEXT("format"),
147→		Packet.Format == EPerceptionImageFormat::PNG ? TEXT("png") : TEXT("jpeg"));
148→	Root->SetNumberField(TEXT("frame_number"), static_cast<double>(Packet.FrameNumber));
149→	Root->SetNumberField(TEXT("timestamp"), Packet.Timestamp);
150→
151→	// Camera
152→	TSharedRef<FJsonObject> CameraObj = MakeShared<FJsonObject>();
153→	TArray<TSharedPtr<FJsonValue>> LocArr;
154→	LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.X));
155→	LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.Y));
156→	LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.Z));
157→	CameraObj->SetArrayField(TEXT("location"), LocArr);
158→
159→	TArray<TSharedPtr<FJsonValue>> RotArr;
160→	RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Pitch));
161→	RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Yaw));
162→	RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Roll));
163→	CameraObj->SetArrayField(TEXT("rotation"), RotArr);
164→	CameraObj->SetNumberField(TEXT("fov"), Packet.Metadata.Camera.FOV);
165→	Root->SetObjectField(TEXT("camera"), CameraObj);
166→
167→	// Viewport
168→	TSharedRef<FJsonObject> ViewportObj = MakeShared<FJsonObject>();
169→	TArray<TSharedPtr<FJsonValue>> SizeArr;
170→	SizeArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.ViewportSize.X));
171→	SizeArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.ViewportSize.Y));
172→	ViewportObj->SetArrayField(TEXT("size"), SizeArr);
173→	ViewportObj->SetStringField(TEXT("type"), Packet.Metadata.ViewportType);
174→	Root->SetObjectField(TEXT("viewport"), ViewportObj);
175→
176→	// Selection
177→	TArray<TSharedPtr<FJsonValue>> SelArr;
178→	for (const FString& Name : Packet.Metadata.SelectedActors)
179→	{
180→		SelArr.Add(MakeShared<FJsonValueString>(Name));
181→	}
182→	Root->SetArrayField(TEXT("selection"), SelArr);
183→
184→	// Scene
185→	TSharedRef<FJsonObject> SceneObj = MakeShared<FJsonObject>();
186→	SceneObj->SetStringField(TEXT("map"), Packet.Metadata.MapName);
187→	SceneObj->SetNumberField(TEXT("actor_count"), Packet.Metadata.ActorCount);
188→	Root->SetObjectField(TEXT("scene"), SceneObj);
189→
190→	// Timing
191→	TSharedRef<FJsonObject> TimingObj = MakeShared<FJsonObject>();
192→	TimingObj->SetNumberField(TEXT("delta_time"), Packet.Metadata.DeltaTime);
193→	TimingObj->SetNumberField(TEXT("fps"), Packet.Metadata.FPS);
194→	Root->SetObjectField(TEXT("timing"), TimingObj);
195→
196→	// Serialize
197→	FString JsonBody;
198→	TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&JsonBody);
199→	FJsonSerializer::Serialize(Root, Writer);
200→
201→	SendJsonResponse(OnComplete, JsonBody);
202→	return true;
203→}
