324→bool FPerceptionEndpoint::HandleSingle(const FHttpServerRequest& Request,
325→                                        const FHttpResultCallback& OnComplete)
326→{
327→	if (!Subsystem)
328→	{
329→		SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem not available\"}"), 503);
330→		return true;
331→	}
332→
333→	// If not capturing, start a temporary capture
334→	const bool WasCapturing = Subsystem->IsCapturing();
335→	if (!WasCapturing)
336→	{
337→		Subsystem->RequestSingleFrame();
338→	}
339→
340→	// Give the frame a moment to arrive, then try to read
341→	// We schedule a delayed response via async
342→	AsyncTask(ENamedThreads::GameThread, [this, OnComplete, WasCapturing]()
343→	{
344→		if (!Subsystem)
345→		{
346→			SendJsonResponse(OnComplete, TEXT("{\"error\":\"Subsystem destroyed\"}"), 500);
347→			return;
348→		}
349→
350→		// Try to get a frame with a brief spin (up to 500ms)
351→		FPerceptionPacket Packet;
352→		constexpr float MaxWait = 0.5f;
353→		constexpr float PollInterval = 0.05f;
354→		float Waited = 0.0f;
355→
356→		while (Waited < MaxWait)
357→		{
358→			Packet = Subsystem->GetLatestPacket();
359→			if (Packet.bValid)
360→			{
361→				break;
362→			}
363→			FPlatformProcess::Sleep(PollInterval);
364→			Waited += PollInterval;
365→		}
366→
367→		// Stop if we started it
368→		if (!WasCapturing)
369→		{
370→			Subsystem->StopCapture();
371→		}
372→
373→		if (!Packet.bValid)
374→		{
375→			SendJsonResponse(OnComplete, TEXT("{\"error\":\"Capture timed out\"}"), 408);
376→			return;
377→		}
378→
379→		// Build the same JSON response as HandleFrame
380→		TSharedRef<FJsonObject> Root = MakeShared<FJsonObject>();
381→		FString ImageBase64 = FBase64::Encode(Packet.ImageData.GetData(), Packet.ImageData.Num());
382→		Root->SetStringField(TEXT("image"), ImageBase64);
383→		Root->SetNumberField(TEXT("width"), Packet.Width);
384→		Root->SetNumberField(TEXT("height"), Packet.Height);
385→		Root->SetStringField(TEXT("format"),
386→			Packet.Format == EPerceptionImageFormat::PNG ? TEXT("png") : TEXT("jpeg"));
387→		Root->SetNumberField(TEXT("frame_number"), static_cast<double>(Packet.FrameNumber));
388→		Root->SetNumberField(TEXT("timestamp"), Packet.Timestamp);
389→
390→		TSharedRef<FJsonObject> CameraObj = MakeShared<FJsonObject>();
391→		TArray<TSharedPtr<FJsonValue>> LocArr;
392→		LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.X));
393→		LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.Y));
394→		LocArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Location.Z));
395→		CameraObj->SetArrayField(TEXT("location"), LocArr);
396→		TArray<TSharedPtr<FJsonValue>> RotArr;
397→		RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Pitch));
398→		RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Yaw));
399→		RotArr.Add(MakeShared<FJsonValueNumber>(Packet.Metadata.Camera.Rotation.Roll));
400→		CameraObj->SetArrayField(TEXT("rotation"), RotArr);
401→		CameraObj->SetNumberField(TEXT("fov"), Packet.Metadata.Camera.FOV);
402→		Root->SetObjectField(TEXT("camera"), CameraObj);
403→
404→		TSharedRef<FJsonObject> SceneObj = MakeShared<FJsonObject>();
405→		SceneObj->SetStringField(TEXT("map"), Packet.Metadata.MapName);
406→		SceneObj->SetNumberField(TEXT("actor_count"), Packet.Metadata.ActorCount);
407→		Root->SetObjectField(TEXT("scene"), SceneObj);
408→
409→		TArray<TSharedPtr<FJsonValue>> SelArr;
410→		for (const FString& Name : Packet.Metadata.SelectedActors)
411→		{
412→			SelArr.Add(MakeShared<FJsonValueString>(Name));
413→		}
414→		Root->SetArrayField(TEXT("selection"), SelArr);
415→
416→		FString JsonBody;
417→		TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&JsonBody);
418→		FJsonSerializer::Serialize(Root, Writer);
419→
420→		SendJsonResponse(OnComplete, JsonBody);
421→	});
422→
423→	return true;  // We'll respond asynchronously
424→}
425→
426→void FPerceptionEndpoint::SendJsonResponse(const FHttpResultCallback& OnComplete,
427→                                            const FString& JsonBody, int32 StatusCode)
428→{
429→	auto Response = FHttpServerResponse::Create(JsonBody, TEXT("application/json"));
430→	OnComplete(MoveTemp(Response));
431→}
