 1→// PixelBus.h
 2→// Lock-free ring buffer with latest-frame latch semantics.
 3→// Producer (render thread) writes frames, consumer (HTTP handler) reads the latest.
 4→
 5→#pragma once
 6→
 7→#include "CoreMinimal.h"
 8→#include "PerceptionTypes.h"
 9→
10→class FPixelBus
11→{
12→public:
13→	FPixelBus();
14→
15→	/** Producer: write a completed frame into the next slot. Thread-safe. */
16→	void WriteFrame(TArray<FColor>&& Pixels, FIntPoint Size,
17→	                int64 FrameNumber, double Timestamp);
18→
19→	/** Consumer: read the latest completed frame. Returns false if no frame available. */
20→	bool ReadLatest(TArray<FColor>& OutPixels, FIntPoint& OutSize,
21→	                int64& OutFrameNumber, double& OutTimestamp) const;
22→
23→	/** Check if a new frame has arrived since the given frame number. */
24→	bool HasNewFrame(int64 LastSeenFrame) const;
25→
26→	/** Get the latest frame number (0 if no frames written). */
27→	int64 GetLatestFrameNumber() const;
28→
29→	/** Attach metadata to the most recently written frame. Call from game thread. */
30→	void AttachMetadata(const FPerceptionMetadata& Metadata);
31→
32→	/** Read the latest frame as a full perception packet (before encode). */
33→	bool ReadLatestWithMetadata(TArray<FColor>& OutPixels, FIntPoint& OutSize,
34→	                            FPerceptionMetadata& OutMetadata,
35→	                            int64& OutFrameNumber, double& OutTimestamp) const;
36→
37→private:
38→	struct FFrameSlot
39→	{
40→		TArray<FColor> Pixels;
41→		FIntPoint Size = FIntPoint::ZeroValue;
42→		FPerceptionMetadata Metadata;
43→		int64 FrameNumber = 0;
44→		double Timestamp = 0.0;
45→		FThreadSafeBool bReady;
46→	};
47→
48→	static constexpr int32 NUM_SLOTS = 3;
49→	FFrameSlot Slots[NUM_SLOTS];
50→
51→	TAtomic<int32> WriteIndex;
52→	TAtomic<int64> LatestFrame;
53→
54→	// Critical section for metadata attachment (game thread only)
55→	mutable FCriticalSection MetadataLock;
56→};
57→

  1→// PixelBus.cpp
  2→
  3→#include "PixelBus.h"
  4→
  5→FPixelBus::FPixelBus()
  6→	: WriteIndex(0)
  7→	, LatestFrame(0)
  8→{
  9→}
 10→
 11→void FPixelBus::WriteFrame(TArray<FColor>&& Pixels, FIntPoint Size,
 12→                           int64 FrameNumber, double Timestamp)
 13→{
 14→	// Advance write index (wraps around NUM_SLOTS)
 15→	const int32 SlotIndex = WriteIndex.Load() % NUM_SLOTS;
 16→
 17→	FFrameSlot& Slot = Slots[SlotIndex];
 18→	Slot.bReady = false;  // Mark slot as being written
 19→
 20→	Slot.Pixels = MoveTemp(Pixels);
 21→	Slot.Size = Size;
 22→	Slot.FrameNumber = FrameNumber;
 23→	Slot.Timestamp = Timestamp;
 24→
 25→	Slot.bReady = true;  // Mark slot as readable
 26→
 27→	// Update latest frame counter and advance write index
 28→	LatestFrame.Store(FrameNumber);
 29→	WriteIndex.Store(SlotIndex + 1);
 30→}
 31→
 32→bool FPixelBus::ReadLatest(TArray<FColor>& OutPixels, FIntPoint& OutSize,
 33→                           int64& OutFrameNumber, double& OutTimestamp) const
 34→{
 35→	// Find the slot with the highest frame number that is ready
 36→	int64 BestFrame = 0;
 37→	int32 BestSlot = -1;
 38→
 39→	for (int32 i = 0; i < NUM_SLOTS; ++i)
 40→	{
 41→		if (Slots[i].bReady && Slots[i].FrameNumber > BestFrame)
 42→		{
 43→			BestFrame = Slots[i].FrameNumber;
 44→			BestSlot = i;
 45→		}
 46→	}
 47→
 48→	if (BestSlot < 0)
 49→	{
 50→		return false;
 51→	}
 52→
 53→	const FFrameSlot& Slot = Slots[BestSlot];
 54→	OutPixels = Slot.Pixels;  // Copy
 55→	OutSize = Slot.Size;
 56→	OutFrameNumber = Slot.FrameNumber;
 57→	OutTimestamp = Slot.Timestamp;
 58→	return true;
 59→}
 60→
 61→bool FPixelBus::HasNewFrame(int64 LastSeenFrame) const
 62→{
 63→	return LatestFrame.Load() > LastSeenFrame;
 64→}
 65→
 66→int64 FPixelBus::GetLatestFrameNumber() const
 67→{
 68→	return LatestFrame.Load();
 69→}
 70→
 71→void FPixelBus::AttachMetadata(const FPerceptionMetadata& Metadata)
 72→{
 73→	FScopeLock Lock(&MetadataLock);
 74→
 75→	// Attach to the most recently written slot
 76→	int64 BestFrame = 0;
 77→	int32 BestSlot = -1;
 78→
 79→	for (int32 i = 0; i < NUM_SLOTS; ++i)
 80→	{
 81→		if (Slots[i].bReady && Slots[i].FrameNumber > BestFrame)
 82→		{
 83→			BestFrame = Slots[i].FrameNumber;
 84→			BestSlot = i;
 85→		}
 86→	}
 87→
 88→	if (BestSlot >= 0)
 89→	{
 90→		Slots[BestSlot].Metadata = Metadata;
 91→	}
 92→}
 93→
 94→bool FPixelBus::ReadLatestWithMetadata(TArray<FColor>& OutPixels, FIntPoint& OutSize,
 95→                                       FPerceptionMetadata& OutMetadata,
 96→                                       int64& OutFrameNumber, double& OutTimestamp) const
 97→{
 98→	FScopeLock Lock(&MetadataLock);
 99→
100→	int64 BestFrame = 0;
101→	int32 BestSlot = -1;
102→
103→	for (int32 i = 0; i < NUM_SLOTS; ++i)
104→	{
105→		if (Slots[i].bReady && Slots[i].FrameNumber > BestFrame)
106→		{
107→			BestFrame = Slots[i].FrameNumber;
108→			BestSlot = i;
109→		}
110→	}
111→
112→	if (BestSlot < 0)
113→	{
114→		return false;
115→	}
116→
117→	const FFrameSlot& Slot = Slots[BestSlot];
118→	OutPixels = Slot.Pixels;
119→	OutSize = Slot.Size;
120→	OutMetadata = Slot.Metadata;
121→	OutFrameNumber = Slot.FrameNumber;
122→	OutTimestamp = Slot.Timestamp;
123→	return true;
124→}
