 1→// FrameProducer.h
 2→// Hooks the backbuffer presentation and performs GPU->CPU readback.
 3→// Runs the readback on the render thread with a throttle gate.
 4→
 5→#pragma once
 6→
 7→#include "CoreMinimal.h"
 8→#include "RHI.h"
 9→
10→class FPixelBus;
11→
12→class FFrameProducer
13→{
14→public:
15→	FFrameProducer();
16→	~FFrameProducer();
17→
18→	/** Begin capturing frames. Hooks OnBackBufferReadyToPresent. */
19→	void Start(FPixelBus* InPixelBus);
20→
21→	/** Stop capturing and unhook the delegate. */
22→	void Stop();
23→
24→	/** Set minimum interval between captures (1/MaxFPS). */
25→	void SetThrottleInterval(double Seconds);
26→
27→	/** True if currently hooked and capturing. */
28→	bool IsActive() const { return bActive; }
29→
30→private:
31→	/** Called on the render thread when the backbuffer is ready. */
32→	void OnFrameBufferReady(SWindow& SlateWindow, const FTextureRHIRef& FrameBuffer);
33→
34→	FDelegateHandle DelegateHandle;
35→	FPixelBus* PixelBus = nullptr;
36→
37→	double MinCaptureInterval = 0.2;  // 5 fps default
38→	double LastCaptureTime = 0.0;
39→	TAtomic<int64> FrameCounter;
40→	bool bActive = false;
41→};
42→

  1→// FrameProducer.cpp
  2→
  3→#include "FrameProducer.h"
  4→#include "PixelBus.h"
  5→#include "ViewportPerceptionModule.h"
  6→#include "RHICommandList.h"
  7→#include "RenderingThread.h"
  8→#include "Framework/Application/SlateApplication.h"
  9→#include "RHISurfaceDataConversion.h"
 10→
 11→FFrameProducer::FFrameProducer()
 12→	: FrameCounter(0)
 13→{
 14→}
 15→
 16→FFrameProducer::~FFrameProducer()
 17→{
 18→	Stop();
 19→}
 20→
 21→void FFrameProducer::Start(FPixelBus* InPixelBus)
 22→{
 23→	if (bActive)
 24→	{
 25→		return;
 26→	}
 27→
 28→	check(InPixelBus);
 29→	PixelBus = InPixelBus;
 30→
 31→	if (FSlateApplication::IsInitialized())
 32→	{
 33→		DelegateHandle = FSlateApplication::Get().GetRenderer()->OnBackBufferReadyToPresent().AddRaw(
 34→			this, &FFrameProducer::OnFrameBufferReady);
 35→
 36→		bActive = true;
 37→		UE_LOG(LogViewportPerception, Log, TEXT("FrameProducer started (interval=%.2fs)"), MinCaptureInterval);
 38→	}
 39→	else
 40→	{
 41→		UE_LOG(LogViewportPerception, Warning, TEXT("Slate not initialized, cannot hook backbuffer"));
 42→	}
 43→}
 44→
 45→void FFrameProducer::Stop()
 46→{
 47→	if (!bActive)
 48→	{
 49→		return;
 50→	}
 51→
 52→	if (FSlateApplication::IsInitialized() && DelegateHandle.IsValid())
 53→	{
 54→		FSlateApplication::Get().GetRenderer()->OnBackBufferReadyToPresent().Remove(DelegateHandle);
 55→		DelegateHandle.Reset();
 56→	}
 57→
 58→	bActive = false;
 59→	PixelBus = nullptr;
 60→	UE_LOG(LogViewportPerception, Log, TEXT("FrameProducer stopped"));
 61→}
 62→
 63→void FFrameProducer::SetThrottleInterval(double Seconds)
 64→{
 65→	MinCaptureInterval = FMath::Max(Seconds, 0.01);  // Cap at 100fps
 66→}
 67→
 68→void FFrameProducer::OnFrameBufferReady(SWindow& SlateWindow, const FTextureRHIRef& FrameBuffer)
 69→{
 70→	// This runs on the render thread -- must be fast when skipping
 71→
 72→	// Throttle gate: skip if too soon since last capture
 73→	const double Now = FPlatformTime::Seconds();
 74→	if ((Now - LastCaptureTime) < MinCaptureInterval)
 75→	{
 76→		return;
 77→	}
 78→
 79→	if (!PixelBus || !FrameBuffer.IsValid())
 80→	{
 81→		return;
 82→	}
 83→
 84→	LastCaptureTime = Now;
 85→	const int64 PrevFrame = FrameCounter.Load();
 86→	const int64 CurrentFrame = PrevFrame + 1;
 87→	FrameCounter.Store(CurrentFrame);
 88→
 89→	// Read the backbuffer pixels
 90→	const FIntPoint Size = FrameBuffer->GetSizeXY();
 91→	TArray<FColor> Pixels;
 92→
 93→	FReadSurfaceDataFlags ReadFlags(RCM_UNorm);
 94→	ReadFlags.SetLinearToGamma(false);
 95→
 96→	// ReadSurfaceData on the current RHI command list
 97→	FRHICommandListImmediate& RHICmdList = FRHICommandListImmediate::Get();
 98→	RHICmdList.ReadSurfaceData(
 99→		FrameBuffer,
100→		FIntRect(0, 0, Size.X, Size.Y),
101→		Pixels,
102→		ReadFlags
103→	);
104→
105→	if (Pixels.Num() > 0)
106→	{
107→		PixelBus->WriteFrame(MoveTemp(Pixels), Size, CurrentFrame, Now);
108→	}
109→}
