 1→// MetadataCollector.cpp
 2→
 3→#include "MetadataCollector.h"
 4→#include "ViewportPerceptionModule.h"
 5→#include "Editor.h"
 6→#include "Selection.h"
 7→#include "LevelEditorViewport.h"
 8→#include "Engine/World.h"
 9→#include "EngineUtils.h"
